// Root node of tables 0..31, count1 A (32) and B (33); `empty` for 0, 4, 14.
module huff_root (
    input  logic [5:0]  table_no,
    output logic [10:0] root,
    output logic        empty
);
    always_comb begin
        empty = 1'b0;
        case (table_no)
            6'd0: begin root = 11'd0; empty = 1'b1; end
            6'd1: root = 11'd0;
            6'd2: root = 11'd3;
            6'd3: root = 11'd11;
            6'd4: begin root = 11'd0; empty = 1'b1; end
            6'd5: root = 11'd19;
